INSERT INTO `app_settings` VALUES (1,'ticker_mantra_te','శ్రీ స్వామియే శరణం అయ్యప్ప ॐ శ్రీ స్వామియే శరణం అయ్యప్ప',NULL,'2026-11-08 08:52:36.549','2026-11-09 10:52:45.193'),(2,'ticker_mantra_kn','ಶ್ರೀ ಸ್ವಾಮಿಯೇ ಶರಣಂ ಅಯ್ಯಪ್ಪ ॐ ಶ್ರೀ ಸ್ವಾಮಿಯೇ ಶರಣಂ ಅಯ್ಯಪ್ಪ',NULL,'2026-11-08 08:52:36.555','2026-11-09 10:52:45.200'),(3,'ticker_mantra_en','Om Sri Swamiye Saranam Ayyappa ॐ Om Sri Swamiye Saranam Ayyappa',NULL,'2026-11-08 08:52:36.562','2026-11-09 10:52:45.204'),(4,'about_us','A sacred devotional mobile application dedicated to Lord Ayyappa Swamy devotees worldwide featuring accurate daily Panchangam, auspicious 2026 Uttara Phalguni dates, authentic Pooja procedures, and multilingual hymns.','About Saranam Ayyappa','2026-11-10 09:50:56.591','2026-11-10 09:50:56.591'),(5,'terms_conditions','Saranam Ayyappa devotional services and content are provided for the spiritual benefit of devotees. All scriptures, stotrams, and astrological data are preserved with reverent authenticity.','Terms & Conditions','2026-11-10 09:50:56.607','2026-11-10 09:50:56.607'),(6,'privacy_policy','Saranam Ayyappa respects devotee privacy. We do not sell or monetize personal data. Selected language preferences and offline audio settings are stored locally on your device.','Privacy Policy','2026-11-10 09:50:56.611','2026-11-10 09:50:56.611'),(7,'sabarimala_guidelines','Official dos and donts for the 41-day Mandala Vratam, Irumudi Kettu preparation, Neelimala trek, and sacred 18 Holy Steps (Pathinettampadi) observance.','Sabarimala Pilgrimage Guidelines','2026-11-10 09:50:56.616','2026-11-10 09:50:56.616');
