INSERT INTO `content_translations` VALUES (1,1,1,'సుప్రభాతం','కౌసల్యా సుప్రజా రామ పూర్వా సంధ్యా ప్రవర్తతే...','2026-11-08 08:52:36.571','2026-11-09 10:52:45.243'),(2,1,2,'ಅಯ್ಯಪ್ಪ ಸುಪ್ರಭಾತ','ಕೌಸಲ್ಯಾ ಸುಪ್ರಜಾ ರಾಮ ಪೂರ್ವಾ ಸಂಧ್ಯಾ ಪ್ರವರ್ತತೇ...','2026-11-08 08:52:36.577','2026-11-09 10:52:45.248'),(3,1,3,'Suprabatham','Kausalya supraja Rama poorva sandhya pravartate...','2026-11-08 08:52:36.584','2026-11-09 10:52:45.253'),(4,2,1,'మాలాధారణ మంత్రం','[ మాలాధారణ మంత్రం ]\n\nజ్ఞానముద్రాం శాస్త్రముద్రాం గురుముద్రాం నమామ్యహమ్ |\nవనముద్రాం శుద్ధముద్రాం రుద్రముద్రాం నమామ్యహమ్ |\nశాంతముద్రాం సత్యముద్రాం వ్రతముద్రాం నమామ్యహమ్ |\nశబర్వాశ్రమ సత్యేన ముద్రాం పాతు సదాపిమే |\nగురుదక్షిణయాపూర్వం తస్యనుగ్రహకారిణే |\nశరణాగత ముద్రాఖ్యం త్వన్ముద్రాం ధారయామ్యహం |\nచిన్ముద్రాం ఖేచరీముద్రాం భద్రముద్రాం నమామ్యహం |\nశబర్వాచల ముద్రాయై నమస్తుభ్యం నమోనమః |\nఅష్టాదశం మహాసారం శాస్త్రదర్శనకారణం |\nవిదితం శుద్ధముత్కృష్టం సన్నిధానం నమామ్యహం!\nఊరుజల వాపురం చైవ భైరవద్యన్న సేవితం |\nవిష్ణుమాయాన్వితం శాస్తా పరివారం నమామ్యహం ||\n\n----------------------------------------\n\nస్వామి......... .........యే శరణమయ్యప్ప\n\n[ దీక్ష విరమణ మంత్రము ]\n\nఅపూర్వమచలారోహ | దివ్యదర్శన కారణాత్ |\nశాస్తృ ముద్రాత్ మహాదేవ | దేహి మే వ్రతవిమోచనమ్ ||\n\n----------------------------------------\n\n[ మొదటి సంవత్సరం నుండి 18 సంవత్సరముల వరకు మాల వేసుకున్న స్వాముల పేర్లు ]\n\n1వ సంవత్సరం - కన్ని(శరము) స్వామి\n2వ సంవత్సరం - కత్తి స్వామి\n3వ సంవత్సరం - ఘంట స్వామి\n4వ సంవత్సరం - గద స్వామి\n5వ సంవత్సరం - విల్లు స్వామి\n6వ సంవత్సరం - జ్యోతి స్వామి\n7వ సంవత్సరం - సూర్య స్వామి\n8వ సంవత్సరం - చంద్ర స్వామి\n9వ సంవత్సరం - వేలు(త్రిశూల) స్వామి\n10వ సంవత్సరం - విష్ణు చక్ర స్వామి\n11వ సంవత్సరం - శంఖం స్వామి\n12వ సంవత్సరం - నాగాభరణం స్వామి\n13వ సంవత్సరం - శ్రీ హరి స్వామి\n14వ సంవత్సరం - పద్మ స్వామి\n15వ సంవత్సరం - శ్రీ (త్రిశూల) స్వామి\n16వ సంవత్సరం - శబరిగిరి స్వామి\n17వ సంవత్సరం - ఓంకారో స్వామి\n18వ సంవత్సరం - నారికేళ స్వామి','2026-11-08 08:52:36.594','2026-11-09 10:52:45.316'),(5,2,2,'ಮಾಲಾಧಾರಣ ಮಂತ್ರ','ಜ್ಞಾನಮುದ್ರಾಂ ಶಾಸ್ತ್ರಮುದ್ರಾಂ\n    ಗುರುಮುದ್ರಾಂ ನಮಾಮ್ಯಹಮ್\n    \n    ವನಮುದ್ರಾಂ ಶುದ್ಧಮುದ್ರಾಂ\n    ರುದ್ರಮುದ್ರಾಂ ನಮಾಮ್ಯಹಮ್\n    \n    ಶಾಂತಮುದ್ರಾಂ ಸತ್ಯಮುದ್ರಾಂ\n    ವ್ರತಮುದ್ರಾಂ ನಮಾಮ್ಯಹಮ್\n    \n    ಶಬರ್ಯಾಶ್ರಮ ಸತ್ಯೇನ ಮುದ್ರಾಂ ಪಾತು ಸದಾಪಿ ಮೇ\n    \n    ಗುರುದಕ್ಷಿಣಯಾ ಪೂರ್ವಂ ತಸ್ಯಾನುಗ್ರಹ ಕಾರಿಣೇ\n    ಶರಣಾಗತ ಮುದ್ರಾಖ್ಯಂ ತ್ವನ್ ಮುದ್ರಾಂ ಧಾರಯಾಮ್ಯಹಮ್\n    \n    ಚಿನ್ಮುದ್ರಾಂ ಖೇಚರೀಮುದ್ರಾಂ ಭದ್ರಮುದ್ರಾಂ ನಮಾಮ್ಯಹಮ್\n    ಶಬರ್ಯಾಚಲ ಮುದ್ರಾಯೈ ನಮಸ್ತುಭ್ಯಂ ನಮೋ ನಮಃ\n    \n    ಮಾಲಾ ವಿಸರ್ಜನ ಮಂತ್ರ\n    \n    ಅಪೂರ್ವಮಚಲಾರೋಹ ದಿವ್ಯದರ್ಶನ ಕಾರಕ\n    ಶಾಸ್ತ್ರೇ ಮುದ್ರಾತ್ಮ ದೇವೇಶ ದೇಹಿಮೇ ವ್ರತಮೋಚನಮ್\n    ಓಂ ಶ್ರೀ ಸ್ವಾಮಿಯೇ ಶರಣಂ ಅಯ್ಯಪ್ಪ\n    \n    ಅಯ್ಯಪ್ಪ ದೀಕ್ಷಾ ವರ್ಷ ನಾಮಗಳು:\n    • 1ನೇ ವರ್ಷ: ಕನ್ನಿ ಸ್ವಾಮಿ (KANNI SWAMY)\n    • 2ನೇ ವರ್ಷ: ಕತ್ತಿ ಸ್ವಾಮಿ (KATHI SWAMY)\n    • 3ನೇ ವರ್ಷ: ಗಂಟ ಸ್ವಾಮಿ (GANTA SWAMY)\n    • 4ನೇ ವರ್ಷ: ಗದಾ ಸ್ವಾಮಿ (GADHA SWAMY)\n    • 5ನೇ ವರ್ಷ: ಪೇರು ಸ್ವಾಮಿ (PERU SWAMY)\n    • 6ನೇ ವರ್ಷ: ಜ್ಯೋತಿ ಸ್ವಾಮಿ (JYOTI SWAMY)\n    • 7ನೇ ವರ್ಷ: ಸೂರ್ಯ ಸ್ವಾಮಿ (SURYA SWAMY)\n    • 8ನೇ ವರ್ಷ: ಚಂದ್ರ ಸ್ವಾಮಿ (CHANDRA SWAMY)\n    • 9ನೇ ವರ್ಷ: ತ್ರಿಶೂಲ ಸ್ವಾಮಿ (TRISHULA SWAMY)\n    • 10ನೇ ವರ್ಷ: ವಿಷ್ಣು ಚಕ್ರ ಸ್ವಾಮಿ (VISHNU CHAKRA SWAMY)\n    • 11ನೇ ವರ್ಷ: ಶಂಖಧಾರ ಸ್ವಾಮಿ (SHANKADHARA SWAMY)\n    • 12ನೇ ವರ್ಷ: ನಾಗಾಭರಣ ಸ್ವಾಮಿ (NAGABHARANA SWAMY)\n    • 13ನೇ ವರ್ಷ: ಶ್ರೀಹರಿ ಸ್ವಾಮಿ (SRIHARI SWAMY)\n    • 14ನೇ ವರ್ಷ: ಶ್ರೀ ಸ್ವಾಮಿ (SRI SWAMY)\n    • 15ನೇ ವರ್ಷ: ಶ್ರೀ ಸ್ವಾಮಿ (SRI SWAMY)\n    • 16ನೇ ವರ್ಷ: ಶ್ರೀ ಶಬರಿ ಸ್ವಾಮಿ (SRI SABARI SWAMY)\n    • 17ನೇ ವರ್ಷ: ಓಂಕಾರ ಸ್ವಾಮಿ (OMKAARA SWAMY)\n    • 18ನೇ ವರ್ಷ: ನಾರಿಕೇಲ ಸ್ವಾಮಿ (NAARIKELA SWAMY)','2026-11-08 08:52:36.597','2026-11-09 10:52:45.321'),(6,2,3,'Maaladharana Mantram','gnaanamudraam shaastrumudraam\n    gurumudraam namaamyaham\n    \n    Vanamudraam Shuddhamudraam\n    Rudramudraam namaamyaham\n    \n    Shaantamudraam satyamudraam\n    Vratamudraam Namaamyaham\n    \n    Shabaryaashrama satyena mudraam paatu sadaapi mae\n    \n    Gurudakshinayaa poorvam tasyaanugraha kaarine\n    Sharanaagata mudraakhyam tvan mudraam dharayayaamyaham\n    \n    Chinmudraam khechareemudraam bhadramudraam namaamyaham\n    Shabaryaachala mudraayai namastubhyam namo namaha\n    \n    Mala Visarjana Mantram\n    \n    Apoorvam Achalam Rohaa\n    Divya darshan\n    Sastre Mudrath Matha Devaa\n    Dehime Vritha Mochanam\n    \n    Om Sri Swami Sharanam Ayyappa\n    \n    Ayyappa Deeksha Years & Swamy Titles:\n    \n    • 1st Year: KANNI SWAMY (The Swamy who takes Ayyappa Deeksha first time)\n    • 2nd Year: KATHI SWAMY\n    • 3rd Year: GANTA SWAMY\n    • 4th Year: GADHA SWAMY\n    • 5th Year: PERU SWAMY\n    • 6th Year: JYOTI SWAMY\n    • 7th Year: SURYA SWAMY\n    • 8th Year: CHANDRA SWAMY\n    • 9th Year: TRISHULA SWAMY\n    • 10th Year: VISHNU CHAKRA SWAMY\n    • 11th Year: SHANKADHARA SWAMY\n    • 12th Year: NAGABHARANA SWAMY\n    • 13th Year: SRIHARI SWAMY\n    • 14th Year: SRI SWAMY\n    • 15th Year: SRI SWAMY\n    • 16th Year: SRI SABARI (RATHIGIRI) SWAMY\n    • 17th Year: OMKAARA SWAMY\n    • 18th Year: NAARIKELA SWAMY','2026-11-08 08:52:36.600','2026-11-09 10:52:45.325'),(7,3,1,'అయ్యప్ప శరణు ఘోష','ఓం శ్రీ స్వామియే శరణమయ్యప్ప\n    హరి హర సుతనే శరణమయ్యప్ప\n    ఆపద్భాంధవనే శరణమయ్యప్ప\n    అనాథరక్షకనే శరణమయ్యప్ప\n    అఖిలాండ కోటి బ్రహ్మాండనాయకనే శరణమయ్యప్ప\n    అన్నదాన ప్రభువే శరణమయ్యప్ప\n    అయ్యప్పనే శరణమయ్యప్ప\n    ఆరియంగావు అయ్యవే శరణమయ్యప్ప\n    ఆచ్చన్ కోవిల్ అరనే శరణమయ్యప్ప\n    కులత్తపుళై బాలకనే శరణమయ్యప్ప\n    ఎరుమేలి శాస్తనే శరణమయ్యప్ప\n    వావరుస్వామినే శరణమయ్యప్ప\n    కన్నిమూల మహా గణపతియే శరణమయ్యప్ప\n    నాగరాజవే శరణమయ్యప్ప\n    మాళికాపురత్త లోకదేవి మాతాయే శరణమయ్యప్ప\n    కురుప్ప స్వామియే శరణమయ్యప్ప\n    సేవిప్ప వర్కానంద మూర్తియే శరణమయ్యప్ప\n    కాశీవాసి యే శరణమయ్యప్ప\n    హరి ద్వార నివాసియే శరణమయ్యప్ప\n    శ్రీ రంగపట్టణ వాసియే శరణమయ్యప్ప\n    కరుప్పటూరు వాసియే శరణమయ్యప్ప\n    పలమూరు ధర్మశాస్తావే శరణమయ్యప్ప\n    సద్గురు నాధనే శరణమయ్యప్ప\n    విలాలి వీరనే శరణమయ్యప్ప\n    వీరమణికంఠనే శరణమయ్యప్ప\n    ధర్మ శాస్త్రవే శరణమయ్యప్ప\n    శరణుఘోషప్రియవే శరణమయ్యప్ప\n    కాంతి మలై వాసనే శరణమయ్యప్ప\n    పొన్నంబలవాసియే శరణమయ్యప్ప\n    పందలశిశువే శరణమయ్యప్ప\n    వావరిన్ తోళనే శరణమయ్యప్ప\n    మోహినీసుతవే శరణమయ్యప్ప\n    కణ్ కండ దైవమే శరణమయ్యప్ప\n    కలియుగవరదనే శరణమయ్యప్ప\n    సర్వరోగ నివారణ ధన్వంతర మూర్తియే శరణమయ్యప్ప\n    మహిషిమర్దననే శరణమయ్యప్ప\n    పూర్ణ పుష్కల నాధనే శరణమయ్యప్ప\n    వన్ పులి వాహననే శరణమయ్యప్ప\n    భక్తవత్సలనే శరణమయ్యప్ప\n    భూలోకనాధనే శరణమయ్యప్ప\n    అయిందుమలైవాసవే శరణమయ్యప్ప\n    శబరి గిరీశనే శరణమయ్యప్ప\n    ఇరుముడి ప్రియనే శరణమయ్యప్ప\n    అభిషేకప్రియనే శరణమయ్యప్ప\n    వేదప్పొరుళీనే శరణమయ్యప్ప\n    నిత్య బ్రహ్మ చారిణే శరణమయ్యప్ప\n    సర్వ మంగళదాయకనే శరణమయ్యప్ప\n    వీరాధివీరనే శరణమయ్యప్ప\n    ఓంకారాప్పొరుళే శరణమయ్యప్ప\n    ఆనందరూపనే శరణమయ్యప్ప\n    భక్త చిత్తాదివాసనే శరణమయ్యప్ప\n    ఆశ్రితవత్స లనే శరణమయ్యప్ప\n    భూత గణాధిపతయే శరణమయ్యప్ప\n    శక్తిరూపనే శరణమయ్యప్ప\n    నాగార్జునసాగరుధర్మ శాస్తవే శరణమయ్యప్ప\n    శాంతమూర్తయే శరణమయ్యప్ప\n    పదునెల్బాబడిక్కి అధిపతియే శరణమయ్యప్ప\n    కట్టాల విషారామనే శరణమయ్యప్ప\n    ఋషికుల రక్షకునే శరణమయ్యప్ప\n    వేదప్రియనే శరణమయ్యప్ప\n    ఉత్తరానక్షత్ర జాతకనే శరణమయ్యప్ప\n    తపోధననే శరణమయ్యప్ప\n    యంగళకుల దైవమే శరణమయ్యప్ప\n    జగన్మోహనే శరణమయ్యప్ప\n    మోహనరూపనే శరణమయ్యప్ప\n    మాధవసుతనే శరణమయ్యప్ప\n    యదుకులవీరనే శరణమయ్యప్ప\n    మామలై వాసనే శరణమయ్యప్ప\n    షణ్ముఖసోదర నే శరణమయ్యప్ప\n    వేదాంతరూపనే శరణమయ్యప్ప\n    శంకర సుతనే శరణమయ్యప్ప\n    శత్రుసంహారిణే శరణమయ్యప్ప\n    సద్గుణమూర్తయే శరణమయ్యప్ప\n    పరాశక్తియే శరణమయ్యప్ప\n    పరాత్పరనే శరణమయ్యప్ప\n    పరంజ్యోతియే శరణమయ్యప్ప\n    హోమప్రియనే శరణమయ్యప్ప\n    గణపతి సోదర నే శరణమయ్యప్ప\n    ధర్మ శాస్త్రావే శరణమయ్యప్ప\n    విష్ణుసుతనే శరణమయ్యప్ప\n    సకల కళా వల్లభనే శరణమయ్యప్ప\n    లోక రక్షకనే శరణమయ్యప్ప\n    అమిత గుణాకరణే శరణమయ్యప్ప\n    అలంకార ప్రియనే శరణమయ్యప్ప\n    కన్ని మారై కప్పవనే శరణమయ్యప్ప\n    భువనేశ్వరనే శరణమయ్యప్ప\n    మాతాపితా గురుదైవమే శరణమయ్యప్ప\n    స్వామియిన్ పూంగావనమే శరణమయ్యప్ప\n    అళుదానదియే శరణమయ్యప్ప\n    అళుదామేడే శరణమయ్యప్ప\n    కల్లిడ్రంకుండ్రే శరణమయ్యప్ప\n    కరిమలై ఏట్రమే శరణమయ్యప్ప\n    కరిమలై ఎరక్కమే శరణమయ్యప్ప\n    పెరియాన్ వట్టమే శరణమయ్యప్ప\n    చెరియాన వట్టమే శరణమయ్యప్ప\n    పంబానదియే శరణమయ్యప్ప\n    పంబయిల్ వేళ్ళక్కే శరణమయ్యప్ప\n    నీలిమలై యే ట్రేమే శరణమయ్యప్ప\n    అప్పాచి మేడే శరణమయ్యప్ప\n    శబరీపీఠమే శరణమయ్యప్ప\n    శరం గుత్తి ఆలే శరణమయ్యప్ప\n    భస్మకుళమే శరణమయ్యప్ప\n    పదునెట్టామ్ బడియే శరణమయ్యప్ప\n    నెయ్యీభి షేకప్రియనే శరణమయ్యప్ప\n    కర్పూర జ్యోతియే శరణమయ్యప్ప\n    జ్యోతిస్వరూపనే శరణమయ్యప్ప\n    మకర జ్యోతియే శరణమయ్యప్ప\n    పందల రాజ కుమారనే శరణమయ్యప్ప','2026-11-08 08:52:36.607','2026-11-09 10:52:45.335'),(8,3,2,'ಶ್ರೀ ಅಯ್ಯಪ್ಪ ಶರಣು ಘೋಷ','ಓಂ ಶ್ರೀ ಸ್ವಾಮಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಹರಿ ಹರ ಸುತನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಆಪದ್ಭಾಂದವನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅನಾಥರಕ್ಷಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಖಿಲಾಂಡ ಕೋಟಿ ಬ್ರಹ್ಮಾಂಡನಾಯಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅನ್ನದಾನ ಪ್ರಭುವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಯ್ಯಪ್ಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಆರಿಯಂಗಾವು ಅಯ್ಯವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಆಚ್ಚನ್ ಕೋವಿಲ್ ಅರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕುಲತ್ತಪುಳೈ ಬಾಲಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಎರುಮೇಲಿ ಶಾಸ್ತನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವಾವರುಸ್ವಾಮಿನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕನ್ನಿಮೂಲ ಮಹಾ ಗಣಪತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ನಾಗರಾಜವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಾಳಿಕಾಪುರತ್ತ ಲೋಕದೇವಿ ಮಾತಾಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕುರುಪ್ಪ ಸ್ವಾಮಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸೇವಿಪ್ಪ ವರ್ಕಾನಂದ ಮೂರ್ತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಾಶೀವಾಸಿ ಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಹರಿ ದ್ವಾರ ನಿವಾಸಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶ್ರೀ ರಂಗಪಟ್ಟಣ ವಾಸಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕರುಪ್ಪಟೂರು ವಾಸಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪಲಮೂರು ಧರ್ಮಶಾಸ್ತಾವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸದ್ಗುರು ನಾಧನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವಿಲಾಲಿ ವೀರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವೀರಮಣಿಕಂಠನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಧರ್ಮ ಶಾಸ್ತ್ರವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶರಣುಘೋಷಪ್ರಿಯವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಾಂತಿ ಮಲೈ ವಾಸನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪೊನ್ನಂಬಲವಾಸಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪಂದಲಶಿಶುವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವಾವರಿನ್ ತೋಳನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮೋಹಿನೀಸುತವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಣ್ ಕಂಡ ದೈವಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಲಿಯುಗವರದನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸರ್ವರೋಗ ನಿವಾರಣ ಧನ್ವಂತರ ಮೂರ್ತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಹಿಷಿಮರ್ದನನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪೂರ್ಣ ಪುಷ್ಕಲ ನಾಧನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವನ್ ಪುಲಿ ವಾಹನನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭಕ್ತವತ್ಸಲನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭೂಲೋಕನಾಧನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಯಿಂದುಮಲೈವಾಸವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶಬರಿ ಗಿರೀಶನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಇರುಮುಡಿ ಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಭಿಷೇಕಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವೇದಪ್ಪೊರುಳೀನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ನಿತ್ಯ ಬ್ರಹ್ಮ ಚಾರಿಣೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸರ್ವ ಮಂಗಳದಾಯಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವೀರಾಧಿವೀರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಓಂಕಾರಾಪ್ಪೊರುಳೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಆನಂದರೂಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭಕ್ತ ಚಿತ್ತಾದಿವಾಸನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಆಶ್ರಿತವತ್ಸ ಲನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭೂತ ಗಣಾಧಿಪತಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶಕ್ತಿರೂಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ನಾಗಾರ್ಜುನಸಾಗರುಧರ್ಮ ಶಾಸ್ತವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶಾಂತಮೂರ್ತಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪದುನೆಲ್ಬಾಬಡಿಕ್ಕಿ ಅಧಿಪತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಟ್ಟಾಲ ವಿಷಾರಾಮನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಋಷಿಕುಲ ರಕ್ಷಕುನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವೇದಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಉತ್ತರಾನಕ್ಷತ್ರ ಜಾತಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ತಪೋಧನನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಯಂಗಳಕುಲ ದೈವಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಜಗನ್ಮೋಹನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮೋಹನರೂಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಾಧವಸುತನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಯದುಕುಲವೀರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಾಮಲೈ ವಾಸನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಷಣ್ಮುಖಸೋದರ ನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವೇದಾಂತರೋಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶಂಕರ ಸುತನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶತ್ರುಸಂಹಾರಿಣೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸದ್ಗುಣಮೂರ್ತಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪರಾಶಕ್ತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪರಾತ್ಪರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪರಂಜ್ಯೋತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಹೋಮಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಗಣಪತಿ ಸೋದರ ನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಧರ್ಮ ಶಾಸ್ತ್ರಾವೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ವಿಷ್ಣುಸುತನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸಕಲ ಕಳಾ ವಲ್ಲಭನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಲೋಕ ರಕ್ಷಕನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಮಿತ ಗುಣಾಕರಣೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಲಂಕಾರ ಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕನ್ನಿ ಮಾರೈ ಕಪ್ಪವನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭುವನೇಶ್ವರನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಾತಾಪಿತಾ ಗುರುದೈವಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಸ್ವಾಮಿಯಿನ್ ಪೂಂಗಾವನಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಳುದಾನದಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಳುದಾಮೇಡೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕಲ್ಲಿಡ್ರಂಕುಂಡ್ರೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕರಿಮಲೈ ಏಟ್ರಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕರಿಮಲೈ ಎರಕ್ಕಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪೆರಿಯಾನ್ ವಟ್ಟಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಚೆರಿಯಾನ ವಟ್ಟಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪಂಬಾನದಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪಂಬಯಿಲ್ ವೇಳಕ್ಕೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ನೀಲಿಮಲೈ ಯೇ ಟ್ರೇಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಅಪ್ಪಾಚಿ ಮೇಡೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶಬರೀಪೀಠಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಶರಂ ಗುತ್ತಿ ಆಲೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಭಸ್ಮಕುಳಮೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪದುನೆಟ್ಟಾಮ್ ಬಡಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ನೆಯ್ಯೀಭಿ ಶೇಕಪ್ರಿಯನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಕರ್ಪೂರ ಜ್ಯೋತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಜ್ಯೋತಿಸ್ವರೂಪನೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಮಕರ ಜ್ಯೋತಿಯೇ ಶರಣಮಯ್ಯಪ್ಪ\n    ಪಂದಲ ರಾಜ ಕುಮಾರನೇ ಶರಣಮಯ್ಯಪ್ಪ','2026-11-08 08:52:36.610','2026-11-09 10:52:45.342'),(9,3,3,'Sri Ayyappa Sharanu Gosha','Om Shree Svaamiye Sharanamayyappa\n    Hari Hara Sutane Sharanamayyappa\n    Aapadbhaandavane Sharanamayyappa\n    Anaadharakshakane Sharanamayyappa\n    Akhilaanda Koti Bra