INSERT INTO `panchangam_translations` VALUES (1,1,1,'శ్రీ పరాభవ సంవత్సరం','ఆశ్వయుజ - కృష్ణ పక్షం','చతుర్దశి 11:28 am','స్వాతి 7:24 am','ఆదివారము','2026-11-08 08:52:36.761',NULL,NULL),(2,1,2,'ಶ್ರೀ ಪರಾಭವ ಸಂವತ್ಸರ','ಆಶ್ವಯುಜ - ಕೃಷ್ಣ ಪಕ್ಷ','ಚತುರ್ದಶಿ 11:28 am','ಸ್ವಾತಿ 7:24 am','ಭಾನುವಾರ','2026-11-08 08:52:36.766',NULL,NULL),(3,1,3,'Sri Parabhava Samvatsaram','Aswayuja - Krishna Paksham','Chaturdasi 11:28 am','Swati 7:24 am','Sunday','2026-11-08 08:52:36.769',NULL,NULL),(4,2,1,'శ్రీ పరాభవ సంవత్సరం','ఆశ్వయుజ - కృష్ణ పక్షం','అమావాస్య 12:32 pm','స్వాతి 7:24 am','సోమవారము','2026-11-09 04:05:44.209','దక్షిణాయనం - శరద్ ఋతువు','{\"date\":\"2026-11-09\",\"dayName\":\"సోమవారము\",\"samvatsara\":\"శ్రీ పరాభవ సంవత్సరం\",\"ayanaRitu\":\"దక్షిణాయనం - శరద్ ఋతువు\",\"maasaPaksha\":\"మాసం: ఆశ్వయుజ - కృష్ణ పక్షం\",\"tithi\":{\"title\":\"తిథి\",\"items\":[\"అమావాస్య: 12:32 pm\",\"తదుపరి పాడ్యమి\"]},\"star\":{\"title\":\"నక్షత్రం\",\"items\":[\"స్వాతి: 07:24 am\",\"తదుపరి విశాఖ\"]},\"yoga\":{\"title\":\"యోగం\",\"items\":[\"సౌభాగ్యము: 02:56 am\",\"శోభనము: 03:09 am\"]},\"karana\":{\"title\":\"కరణం\",\"items\":[\"నాగవము: 12:32 pm\",\"కింస్తుఘ్నము: 01:13 am\",\"బవ: 02:00 pm\"]},\"auspiciousTime\":{\"title\":\"శుభ ఘడియలు\",\"items\":[\"అభిజిత్ ముహూర్తం: 11:37 am - 12:22 pm\",\"అమృతకాలం: 11:48 pm - 01:31 am\",\"బ్రాహ్మీ ముహూర్తం: 4:45 am - 05:33 am\"]},\"inauspiciousTime\":{\"title\":\"అశుభ ఘడియలు\",\"items\":[\"రాహు కాలం: 7:46 am - 09:10 am\",\"యమగండ/కేతుకాలం: 10:35 am - 11:59 am\",\"గుళిక కాలం: 1:24 pm - 02:48 pm\",\"దుర్ముహూర్తం: 12:22 pm - 01:07 pm\",\"వర్జ్యం: 1:27 pm - 03:11 pm\"]},\"sunTimes\":\"సూర్యోదయం: 6:21 am || సూర్యాస్తమయం: 5:38 pm\"}'),(5,2,2,'ಶ್ರೀ ಪರಾಭವ ಸಂವತ್ಸರ','ಆಶ್ವಯುಜ - ಕೃಷ್ಣ ಪಕ್ಷ','ಅಮಾವಾಸ್ಯೆ 12:32 pm','ಸ್ವಾತಿ 7:24 am','ಸೋಮವಾರ','2026-11-09 04:05:44.215','ದಕ್ಷಿಣಾಯನ - ಶರದ್ ಋತು','{\"date\":\"2026-11-09\",\"dayName\":\"ಸೋಮವಾರ\",\"samvatsara\":\"ಶ್ರೀ ಪರಾಭವ ಸಂವತ್ಸರ\",\"ayanaRitu\":\"ದಕ್ಷಿಣಾಯನ - ಶರದ್ ಋತು\",\"maasaPaksha\":\"ಮಾಸ: ಆಶ್ವಯುಜ - ಕೃಷ್ಣ ಪಕ್ಷ\",\"tithi\":{\"title\":\"ತಿಥಿ\",\"items